const body = $json.body ?? {};

const action = String(
  body.action ?? ''
).trim().toUpperCase();

const evento_id = body.evento_id
  ? String(body.evento_id).trim()
  : null;

const categoria = body.categoria
  ? String(body.categoria)
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '_')
  : null;

const visitor_id = body.visitor_id
  ? String(body.visitor_id).trim()
  : null;

let route = 'INVALID';
let error = null;

switch (action) {
  case 'LIST':
  case 'LISTADO':
    route = 'LISTADO';
    break;

  case 'DETAIL':
  case 'DETALLE':
    if (!evento_id) {
      error = 'evento_id es obligatorio';
    } else {
      route = 'DETALLE';
    }
    break;

  case 'FILTER':
  case 'FILTRO':
    if (!categoria) {
      error = 'categoria es obligatoria';
    } else {
      route = 'FILTRO';
    }
    break;

  case 'AVAILABILITY':
  case 'DISPONIBILIDAD':
    if (!evento_id) {
      error = 'evento_id es obligatorio';
    } else {
      route = 'DISPONIBILIDAD';
    }
    break;

  default:
    error = 'Acción no válida';
}

return [{
  json: {
    route,
    action,
    evento_id,
    categoria,
    visitor_id,
    error
  }
}];

