const eventos = $('Filtrar eventos publicables LISTADO')
  .all()
  .map(item => item.json);

const inscripciones = $('Leer inscripciones LISTADO')
  .all()
  .map(item => item.json)
  .filter(item => item.inscripcion_id);

const confirmadasPorEvento = {};

for (const inscripcion of inscripciones) {
  const estado = String(inscripcion.estado ?? '')
    .trim()
    .toUpperCase();

  if (estado !== 'CONFIRMADA') {
    continue;
  }

  const eventoId = String(inscripcion.evento_id ?? '').trim();

  if (!eventoId) {
    continue;
  }

  confirmadasPorEvento[eventoId] =
    (confirmadasPorEvento[eventoId] ?? 0) + 1;
}

const resultado = eventos.map(evento => {
  const capacidad = Number(evento.capacidad ?? 0);

  const inscripciones_confirmadas =
    confirmadasPorEvento[evento.evento_id] ?? 0;

  const cupos_disponibles = Math.max(
    capacidad - inscripciones_confirmadas,
    0
  );

  return {
    evento_id: evento.evento_id,
    nombre: evento.nombre,
    categoria: evento.categoria,
    descripcion: evento.descripcion,
    fecha: evento.fecha,
    hora: evento.hora,
    lugar: evento.lugar,
    capacidad,
    inscripciones_confirmadas,
    cupos_disponibles,
    disponible: cupos_disponibles > 0,
    imagen_url: evento.imagen_url ?? '',
    organizador: evento.organizador,
    estado: evento.estado
  };
});

return [{
  json: {
    ok: true,
    tipo: 'LISTADO',
    resultado_count: resultado.length,
    eventos: resultado
  }
}];

const crypto = require('crypto');

const resultado = $('Calcular disponibilidad LISTADO').first().json;
const entrada = $('Normalizar y validar catálogo').first().json;

return [{
